// Daily signals, forecasts and questions from week.js, generated by build_data.py.
// Character animation and the 14:50 onset time are illustrative; the simulator is daily.
window.P = {};
(function (P) {
  const W = window.WEEK;
  P.DAYS = W.days;
  P.BASE = W.base;

  P.T_END = 168;            // hours in the week
  P.STEP = 1 / 6;           // 10-minute samples
  P.N = P.T_END * 6 + 1;
  // Wake time from the watch: sleep midpoint plus half the sleep duration.
  P.WAKE = P.DAYS.map(D => D.mid + D.sleep / 2);
  P.ATTACK = { start: 6 * 24 + 14 + 50 / 60, end: 6 * 24 + 19 };

  P.dayOf = t => Math.min(6, Math.max(0, Math.floor(t / 24)));
  P.pubTime = d => d * 24 - 3;  // forecast for day d is made at 21:00 the evening before
  P.level = r => (r >= 0.4 ? 'high' : r >= 0.15 ? 'elev' : 'low');
  P.LEVEL_COLOR = { low: '#34c88a', elev: '#f4b13e', high: '#ff6461' };
  P.LEVEL_TEXT = { low: 'Low', elev: 'Elevated', high: 'High' };

  P.sleepScore = D => D.sleep;

  // Sleep intervals; night d ends on the morning of day d.
  P.NIGHTS = P.DAYS.map((D, d) => {
    const end = d * 24 + P.WAKE[d];
    return { start: end - D.sleep, end, score: P.sleepScore(D) };
  });
  P.NIGHTS.push({ start: 6 * 24 + 22.6, end: 7 * 24 + 7, score: null });
  P.asleep = t => P.NIGHTS.some(n => t >= n.start && t < n.end);
  P.inAttack = t => t >= P.ATTACK.start && t < P.ATTACK.end;

  // Questions come from the question policy, asked at 20:30 once the day's watch data is in.
  // The morning heads-up is shown only when the model's forecast for the attack day is not low.
  P.Q_TIME = 20.5;
  P.WARN = P.level(P.DAYS[6].risk) !== 'low';
  P.EVENTS = [
    { id: 'pub5', t: P.pubTime(5), kind: 'forecast', day: 5 },
    { id: 'pub6', t: P.pubTime(6), kind: 'forecast', day: 6 },
    ...P.DAYS.flatMap((D, d) => D.question ? [{ id: 'q' + d, t: d * 24 + P.Q_TIME, kind: 'question', day: d, block: true }] : []),
    ...(P.WARN ? [{ id: 'warn', t: 6 * 24 + 7.5, kind: 'warning', block: true }] : []),
    { id: 'attack', t: P.ATTACK.start, kind: 'attack', block: true },
  ].sort((a, b) => a.t - b.t);

  // Fast-forward everywhere except the last 45 sim-minutes before each notification.
  P.isFast = t => !P.EVENTS.some(e => e.block && t >= e.t - 0.75 && t < e.t);

  P.CAPTIONS = [
    { t: 0, text: 'Anna lives her week. Her watch collects the data. The model forecasts tomorrow.' },
  ];

  P.fmtClock = t => {
    const m = ((Math.round(t * 60) % 1440) + 1440) % 1440;
    return String(Math.floor(m / 60)).padStart(2, '0') + ':' + String(m % 60).padStart(2, '0');
  };
  P.fmtDay = t => { const D = P.DAYS[P.dayOf(t)]; return D.name + ' ' + D.date + ' ' + new Date(D.iso + 'T12:00').toLocaleString('en', { month: 'short' }); };

  // Repeat the actual daily measurements as stepped chart values.
  P.HR = Array.from({ length: P.N }, (_, i) => P.DAYS[P.dayOf(i * P.STEP)].rhr);
  P.ST = Array.from({ length: P.N }, (_, i) => P.DAYS[P.dayOf(i * P.STEP)].stress);
  P.at = (arr, t) => arr[Math.min(P.N - 1, Math.max(0, Math.round(t / P.STEP)))];
})(window.P);
